from dateutil.relativedelta import relativedelta
def standardize_time(value):
    try:
        time = datetime.datetime.strptime(value, '%H:%M')
        if time.hour >= 18:
            return value
        else:
            return time + relativedelta(hours=18)
    except ValueError:
        return None
return standardize_time(value)
return value

